func (q *Queries) ListVendors(ctx context.Context, arg ListVendorsParams) ([]Vendor, error) {
	rows, err := q.db.QueryContext(ctx, listVendors,
		arg.TenantID,
		arg.Column2,
		arg.Column3,
		arg.Column4,
		arg.Column5,
		arg.Limit,
		arg.Offset,
		arg.Column8,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Vendor{}
	for rows.Next() {
		var i Vendor
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.VendorCode,
			&i.VendorName,
			&i.VendorEmail,
			&i.VendorMobile,
			&i.VendorNickName,
			&i.ActivityType,
			&i.Gstin,
			&i.Pan,
			&i.Pin,
			&i.CountryName,
			&i.StateName,
			&i.CityName,
			&i.Msme,
			&i.MsmeRegistrationNumber,
			&i.MsmeStartDate,
			&i.MsmeEndDate,
			&i.MaterialNature,
			&i.GstDefaulted,
			&i.Section206abVerified,
			&i.BeneficiaryName,
			&i.RemarksAddress,
			&i.CommonBankDetails,
			&i.IncomeTaxType,
			&i.ProjectID,
			&i.FromAccountType,
			&i.AccountName,
			&i.ShortName,
			&i.Parent,
			&i.CodeAutoGenerated,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AccountNumber,
			&i.NameOfBank,
			&i.IfscCode,
			&i.DocumentUrl,
			&i.AccountType,
			&i.Status,
			&i.MsmeClassification,
			&i.Address,
			&i.SignatureUrl,
			&i.OrgID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

